    const lineRows = B.lines.map((x, i) => `<div style="display:grid;grid-template-columns:repeat(5,minmax(0,1fr)) minmax(0,1.6fr) auto;gap:6px;margin-top:6px;align-items:center"><input class="inp" data-bkl="${i}:n" type="number" min="1" max="33" title="${esc(T('Мест', 'Anzahl', 'Count', 'Саны'))}" placeholder="${esc(T('шт', 'Stk', 'pcs', 'дана'))}" value="${esc(x.n)}"><input class="inp" data-bkl="${i}:l" type="number" min="1" max="400" placeholder="L cm" value="${esc(x.l)}"><input class="inp" data-bkl="${i}:w" type="number" min="1" max="400" placeholder="W cm" value="${esc(x.w)}"><input class="inp" data-bkl="${i}:h" type="number" min="1" max="220" placeholder="H cm" value="${esc(x.h)}"><input class="inp" data-bkl="${i}:kg" type="number" min="1" max="1200" placeholder="kg" value="${esc(x.kg)}"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center"><label class="fl" style="margin:0;display:flex;gap:4px;align-items:center"><input type="checkbox" data-bkl="${i}:stack"${x.stack ? ' checked' : ''}>${esc(T('штаб.', 'stapelb.', 'stack.', 'қабат.'))}</label>${lineOver(x) ? `<span class="note" data-oversize style="color:var(--chip-yellow-fg,#8a5a00)">${esc(T('негабарит — согласуйте с диспетчером', 'Übermaß — mit der Disposition abstimmen', 'oversize — agree with dispatch', 'габариттен тыс — диспетчермен келісіңіз'))}</span>` : ''}</div><button class="btn sm grey" data-act="bkLineDel" data-v="${i}" title="${esc(T('Удалить строку', 'Zeile entfernen', 'Remove line', 'Жолды жою'))}">×</button></div>`).join('');
    return card(T('Груз: категории (до 6)', 'Ware (bis 6 Kategorien)', 'Goods (categories, up to 6)', 'Жүк (6 санатқа дейін)'), `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:8px">${GOODS.map(gc).join('')}</div>
${B.goods.length ? '' : `<p class="note" data-goods-none>${esc(T('Выберите хотя бы одну категорию груза.', 'Mindestens eine Warenkategorie wählen.', 'Choose at least one goods category.', 'Кемінде бір жүк санатын таңдаңыз.'))}</p>`}
${B.goods.length && !zs.length ? `<p class="note" data-goods-mix style="color:var(--chip-red-fg)">${esc(MIX)}</p>` : ''}
<label class="fl" style="margin-top:10px">${esc(T('Примечание к грузу (необязательно)', 'Hinweis zur Ware (optional)', 'Remark on the goods (optional)', 'Жүк туралы ескерту (міндетті емес)'))}${inp('goodsRemark', B.goodsRemark, 'text', ' maxlength="250"')}</label>
<div class="bk-grid" style="margin-top:10px" data-load><label class="fl">${esc(T('Температурный класс', 'Temperaturklasse', 'Temp. class', 'Температура класы'))}${sel('zone', B.zone, zopts)}</label><label class="fl">${esc(T('Паллеты', 'Paletten', 'Pallets', 'Паллеттер'))}${inp('pallets', B.pallets, 'number', ' min="0.5" max="33" step="0.5"')}</label><label class="fl">${esc(T('Вес брутто, кг', 'Bruttogewicht, kg', 'Gross weight, kg', 'Брутто салмағы, кг'))}${inp('kg', B.kg, 'number', ' min="1" max="20000" step="1"')}</label><p class="note span-all" data-avg style="margin:0${avg > RT.max_kg_per_pallet ? ';color:var(--chip-red-fg)' : ''}">${avg != null ? `≈ ${LF.int(avg)} ${esc(T('кг в среднем на паллету', 'kg je Palette im Schnitt', 'kg average per pallet', 'кг паллетаға орташа'))}${avg > RT.max_kg_per_pallet ? ' — ' + esc(T('Больше 1 200 кг на паллету — превышение допустимой нагрузки (ось / паллета).', 'Mehr als 1 200 kg je Palette — zulässige Last (Achse / Palette) überschritten.', 'More than 1,200 kg per pallet — permissible load (axle / pallet) exceeded.', '1 200 кг-нан артық — рұқсат етілген жүктемеден асу (ось / паллет).')) : ''}` : esc(T('Введите вес — он нужен для цены, вместимости и проверки осей.', 'Gewicht eingeben — es wird für Preis, Kapazität und Achslastprüfung benötigt.', 'Enter the weight — it is used for the price, capacity and the axle check.', 'Салмақты енгізіңіз — ол баға, сыйымдылық және ось жүктемесін тексеру үшін қажет.'))}</p>${zs.length && B.goods.length ? `<p class="note span-all" style="margin:0" data-tc-fit>${esc(T('Режим подобран по грузу; недоступные режимы отключены.', 'Temperaturbereich passend zur Ware; unpassende sind gesperrt.', 'Temperature class matched to the goods; unsuitable ones are disabled.', 'Режим жүкке сай таңдалды; сәйкес емес режимдер белгіленген.'))}</p>` : ''}</div>
${palletRows}
<details${B.lines.length ? ' open' : ''} style="margin-top:10px"><summary class="note" style="cursor:pointer">${esc(T('Размеры мест (необязательно)', 'Packstückmaße (optional)', 'Place dimensions (optional)', 'Орын өлшемдері (міндетті емес)'))} · ${B.lines.reduce((a, x) => a + (+x.n || 0), 0)}</summary><p class="note">${esc(T('Д×Ш×В в см и вес одного места; высота до 220 см.', 'L×B×H in cm und Gewicht je Packstück; Höhe bis 220 cm.', 'L×W×H in cm and weight per package; height up to 220 cm.', 'Ұз×Ен×Биік см және бір орынның салмағы; биіктігі 220 см-ге дейін.'))}</p>${lineRows}<button class="btn sm grey" style="margin-top:6px" data-act="bkLine">+ ${esc(T('место', 'Packstück', 'place', 'орын'))}</button></details>
${warns.length ? `<p class="note" style="margin:6px 0 0" data-warn-title><b>${esc(T('Проверьте вес и места (бронирование всё равно возможно):', 'Gewicht und Packstücke prüfen (Buchung trotzdem möglich):', 'Check weight and places (booking still possible):', 'Салмақ пен орындарды тексеріңіз (брондау бәрібір мүмкін):'))}</b></p>` : ''}${warns.map(w => `<div class="tinted-row yellow" style="margin-top:6px">${ic('alert', 14)} <span style="flex:1">${esc(w)}</span></div>`).join('')}`);
