        const e = { id: 'EX-' + no, cust: S.custId, from: LOCS[B.pCity].hub, to: LOCS[B.dCity].hub, zone: B.zone, pal: Math.min(33, Math.max(1, Math.ceil(+B.pallets))), kg: +B.kg, want: B.deliverBy + ':00+05:00', due, sig: { ceo: null, ana: null, log: null }, status: 'pending', surcharge: 35, notified: fdt(NOW), log: [{ t: fdt(NOW).slice(-5), text: T('Запрос из портала · ', 'Anfrage aus dem Portal · ', 'Request from the portal · ', 'Порталдан сұрау · ') + b.id }], load: '', booking: b.id };
        S.express.unshift(e); b.express_id = e.id; audit('Portal', b.id, 'Express requested', e.id);
