  const LAZY = ['kg', 'pallets', 'declared', 'dg.net', 'dg.dry'];   /* typed numbers only set the state; the form repaints on change (blur / Enter), so the focus stays in the field */
  document.addEventListener('input', e => { const t = e.target; if (t.dataset && t.dataset.bk && t.type !== 'checkbox') { const k = t.dataset.bk; setPath(k, t.value); if (k === 'dg.un') { B.dg.un = t.value.replace(/\D/g, '').slice(0, 4); t.value = B.dg.un; } if (k === 'payer.phone') B.payer.phone = t.value.replace(/[^+0-9 ()-]/g, ''); if (k === 'payer.bin' && !B.payer.company.trim() && tinCheck(t.value).valid && kgdLookup(t.value)) B.payer.company = kgdLookup(t.value); if (/^[pd](City|Street|House|Book)$/.test(k)) B.savedAddr = ''; if (/^[pd]Street$/.test(k)) { B[k[0] + 'Manual'] = false; B.done = null; return patchAddr(k[0]); } if (/^[pd]City$/.test(k)) { B[k[0] + 'Street'] = ''; B[k[0] + 'Manual'] = false; } if (k === 'pFrom' || k === 'pTo') B.slot = B.slot && visSlots().some(s => s.date === B.slot) ? B.slot : ''; if (t.dataset.bk === 'pBook' || t.dataset.bk === 'dBook') { const a = me().book.find(x => x.id === t.value); if (a) { const pre = t.dataset.bk[0]; B[pre + 'City'] = a.city; B[pre + 'Street'] = a.street; B[pre + 'House'] = a.house; B[pre + 'Site'] = a.label; B[pre + 'Hours'] = a.hours || ''; } } if (t.dataset.bk === 'pCity' || t.dataset.bk === 'dCity') B.slot = ''; if (t.dataset.bk === 'zone' || t.dataset.bk === 'pallets') B.slot = B.slot && slotsFor(B.pCity, B.dCity, +B.pallets || 1, +B.kg).some(s => s.date === B.slot && s.ok) ? B.slot : ''; B.done = null; if (!LAZY.includes(k)) render(); } else if (t.dataset && t.dataset.bkl && t.type !== 'checkbox') { const [i, k] = t.dataset.bkl.split(':'); B.lines[+i][k] = t.value; } });
  const nb0 = globalThis.newBooking;
