  document.addEventListener('change', e => { const t = e.target; if (t.type !== 'checkbox') { if (t.dataset.bk && LAZY.includes(t.dataset.bk)) { setPath(t.dataset.bk, t.value); render(); } else if (t.dataset.bkl) { const [i, k] = t.dataset.bkl.split(':'); B.lines[+i][k] = t.value; render(); } else if (t.dataset.bkpz != null) { B.pz = B.pz || []; B.pz[+t.dataset.bkpz] = t.value; render(); } return; } if (t.dataset.bk) { setPath(t.dataset.bk, t.checked); if (t.dataset.bk === 'express') B.slot = ''; render(); } else if (t.dataset.bkg) { const c = t.dataset.bkg; if (t.checked && B.goods.length >= 6) { t.checked = false; return toast(T('Не более 6 категорий груза', 'Höchstens 6 Warenkategorien', 'At most 6 goods categories', '6 санаттан аспауы керек'), 'err'); } B.goods = t.checked ? B.goods.concat(c) : B.goods.filter(x => x !== c); const zs = goodsZones(B.goods); if (zs.length && !zs.includes(B.zone)) { const g1 = GOODS.find(x => x.code === B.goods[0]); B.zone = g1 && zs.includes(g1.tc) ? g1.tc : zs[0]; } render(); } else if (t.dataset.bkl) { const [i, k] = t.dataset.bkl.split(':'); B.lines[+i][k] = t.checked; render(); } });
